print('SHEET NAMES:', wb.sheetnames)
print('\nTASK rows 10-50 cols D-L:')
ws=wb['Task']
for r in range(10,51):
    vals=[]
    for c in range(4,13):
        v=ws.cell(r,c).value
        vals.append('' if v is None else str(v))
    print(f"{r:02d}: " + ' | '.join(f"{get_column_letter(c)}={vals[c-4]}" for c in range(4,13)))
print('\nDATA rows 21-38 (all used columns around row):')
ds=wb['Data']
# determine used columns with nonempty in rows 21-38
cols=set()
for r in range(21,39):
    for c in range(1, ds.max_column+1):
        if ds.cell(r,c).value is not None:
            cols.add(c)
if cols:
    start=max(1,min(cols)-2); end=min(ds.max_column,max(cols)+2)
else:
    start=1; end=ds.max_column
print('Data max_row/max_col:', ds.max_row, ds.max_column, 'printing cols', start, '-', end)
for r in range(21,39):
    entries=[]
    for c in range(start,end+1):
        v=ds.cell(r,c).value
        entries.append(f"{get_column_letter(c)}={'' if v is None else v}")
    print(f"{r:02d}: " + ' | '.join(entries))
print('\nTask labels/checks:')
for rng in [(12,17),(19,24),(26,31),(35,50)]:
